<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useWorkbench} from '../stores/workbench'
import {stages,statusNames,progress,blockingReasons,resolveModel,validApproval,fingerprint} from '../lib/domain'
import Icon from '../components/Icon.vue'
import ModelDefaultSelect from '../components/ModelDefaultSelect.vue'
const store=useWorkbench(),route=useRoute(),router=useRouter(),search=ref(''),text=ref(''),skipReason=ref('')
const project=computed(()=>store.state.projects.find(p=>p.id===route.params.id)),selectedId=ref(String(route.query.node??store.catalog.nodes[0].id))
const selected=computed(()=>store.catalog.nodes.find(n=>n.id===selectedId.value)??store.catalog.nodes[0]),nodeState=computed(()=>project.value?.nodes[selected.value.id])
const groups=computed(()=>Object.entries(stages).map(([id,name])=>({id,name,nodes:store.catalog.nodes.filter(n=>n.stage===id&&(n.id+n.name).toLowerCase().includes(search.value.toLowerCase()))})).filter(g=>g.nodes.length))
const reasons=computed(()=>project.value?blockingReasons(project.value,selected.value,store.catalog):[])
const pendingGates=computed(()=>project.value?store.catalog.gates.filter(g=>g.after.every(id=>project.value!.nodes[id].status==='COMPLETED')&&!validApproval(project.value!,g)):[])
watch([selectedId,()=>nodeState.value?.draft],()=>{text.value=nodeState.value?.draft??''},{immediate:true});watch(()=>route.query.node,n=>{if(n)selectedId.value=String(n)})
async function save(complete=false){if(!project.value)return;await store.command({type:'SAVE_NODE',payload:{projectId:project.value.id,nodeId:selected.value.id,text:text.value,complete}},complete?'节点产物已完成，依赖与版本已更新':'草稿已保存')}
async function approve(id:string){const pr=project.value,g=store.catalog.gates.find(x=>x.id===id);if(pr&&g)await store.command({type:'APPROVE_GATE',payload:{projectId:pr.id,gateId:id,fingerprint:fingerprint(pr,g)}},'阶段已确认，后续节点可以继续')}
function choose(id:string){selectedId.value=id;router.replace({query:{node:id}})}
function setBinding(capability:string,modelId:string,scope='NODE'){store.command({type:'SET_BINDING',payload:{projectId:project.value!.id,nodeId:selected.value.id,capability,modelId,scope}},'模型绑定已更新')}
function template(){text.value=JSON.stringify(Object.fromEntries(selected.value.output.requiredFields.map(k=>[k,''])),null,2)}
async function importText(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>2_000_000){store.toast('文字产物请控制在 2MB 内，大文件请上传到素材库','error');return}text.value=await file.text();store.toast('文本已读取，请检查后保存')}
</script>
<template><div v-if="project" class="page-content workspace-page"><div class="workspace-heading"><div><RouterLink to="/projects" class="back-link"><Icon name="ArrowLeft" :size="14"/>我的作品</RouterLink><div class="workspace-title"><h1>{{project.title}}</h1><span v-if="project.sample" class="badge neutral">示例作品</span></div><p>{{project.brief||'把你的创作想法，逐步变成一条作品。'}}</p></div><div class="heading-actions"><button class="btn" @click="store.command({type:'PLAN_PROJECT',payload:{projectId:project.id}},'下一步计划已记录到任务中心')"><Icon name="Route"/>检查下一步</button><RouterLink class="btn primary" :to="{path:'/runs',query:{projectId:project.id,node:selected.id}}"><Icon name="Play" :size="15"/>启动 Agent 协作</RouterLink></div></div><div class="project-model-default"><ModelDefaultSelect scope="PROJECT" :project-id="project.id" label="作品默认模型"/><RouterLink :to="{path:'/workflow',query:{projectId:project.id}}" class="text-link"><Icon name="Workflow" :size="14"/>查看此作品的完整流程</RouterLink></div><div class="workspace-summary"><span><Icon name="Workflow" :size="15"/>{{progress(project)}} / {{store.catalog.nodes.length}} 个节点</span><div class="progress-line"><span :style="{transform:'scaleX('+progress(project)/store.catalog.nodes.length+')'}"/></div><span>预算 ¥{{project.budget.toFixed(2)}}</span><span><i class="status-dot"/>{{store.connection==='server'?'数据库保存':'浏览器保存'}}</span></div><div class="gate-banner" v-for="gate in pendingGates" :key="gate.id"><span class="gate-symbol"><Icon name="CheckCheck" :size="20"/></span><div><b>{{gate.name}} · 等你拍板</b><p>{{gate.decision}}</p></div><button class="btn" @click="approve(gate.id)">确认当前版本<Icon name="ArrowRight" :size="14"/></button></div><div class="workspace-grid"><aside class="node-sidebar"><div class="node-sidebar-title"><b>制作流程</b><span>{{store.catalog.nodes.length}}</span></div><div class="node-search"><Icon name="Search" :size="14"/><input v-model="search" placeholder="搜索节点" aria-label="搜索制作节点"></div><div class="node-groups"><section v-for="group in groups" :key="group.id"><h3>{{group.name}}</h3><button v-for="node in group.nodes" :key="node.id" :class="['node-item',{selected:selected.id===node.id}]" @click="choose(node.id)"><span :class="['node-indicator',project.nodes[node.id].status]"><Icon v-if="project.nodes[node.id].status==='COMPLETED'" name="Check" :size="11"/><Icon v-else-if="project.nodes[node.id].status==='NEEDS_REVALIDATION'" name="RotateCcw" :size="10"/></span><span>{{node.name}}</span><small>{{node.id}}</small></button></section></div></aside><section class="node-editor"><div class="editor-top"><span class="node-id">{{selected.id}}</span><span :class="['badge',nodeState?.status==='COMPLETED'?'success':'neutral']">{{statusNames[nodeState?.status??'NOT_STARTED']}}</span><span class="muted small">版本 {{nodeState?.revision??0}}</span></div><h2>{{selected.name}}</h2><p class="node-description">{{selected.inputDescription}}</p><div class="node-role"><Icon name="Bot" :size="15"/>{{store.catalog.agents.find(a=>a.id===selected.agentRole)?.name}}<span/>{{selected.responsibility==='A'?'规则明确后可自动执行':selected.responsibility==='B'?'人机协作':'由你主导'}}</div><div class="input-requirements"><span class="field-heading">需要的输入</span><p>{{selected.inputDescription}}</p><div class="dependency-tags"><button v-for="dep in selected.dependsOn" :key="dep" @click="choose(dep)" :class="{done:project.nodes[dep].status==='COMPLETED'}"><Icon :name="project.nodes[dep].status==='COMPLETED'?'CheckCircle2':'Circle'" :size="12"/>{{dep}} {{store.catalog.nodes.find(n=>n.id===dep)?.name}}</button><span v-if="!selected.dependsOn.length" class="muted small">从你的真实想法开始，无前置依赖。</span></div></div><div class="editor-label"><label for="node-output">本节点产物</label><div><button class="text-link" @click="template"><Icon name="Braces" :size="13"/>插入字段模板</button><label class="text-link import-label"><Icon name="Upload" :size="13"/>导入文本<input type="file" accept=".txt,.md,.json" hidden @change="importText"></label></div></div><textarea id="node-output" v-model="text" class="artifact-editor" :placeholder="'在这里整理'+selected.name+'的结果，也可以导入你在其他工具完成的文本。\n\n没有执行器时，手工交付同样可以继续完整流程。'" spellcheck="false"/><div class="required-fields"><span>交付字段</span><code v-for="field in selected.output.requiredFields" :key="field">{{field}}</code></div><div class="blocked-note" v-if="reasons.length"><Icon name="Info" :size="16"/><span>{{reasons[0]}}<small>可以先保存草稿，满足依赖后再标记完成。</small></span></div><div class="editor-actions"><button class="btn" @click="save(false)" :disabled="store.saving"><Icon name="Save" :size="16"/>保存草稿</button><button class="btn primary" @click="save(true)" :disabled="store.saving||!text.trim()||!!reasons.length"><Icon name="Check" :size="16"/>标记产物完成</button></div><details class="skip-control" v-if="['N25','N26'].includes(selected.id)"><summary>该步骤不适用于当前制作路线？</summary><input v-model="skipReason" placeholder="说明原因及替代方式"><button class="btn" @click="store.command({type:'SKIP_NODE',payload:{projectId:project.id,nodeId:selected.id,reason:skipReason}},'已记录不适用原因')">记录并跳过</button></details></section><aside class="node-inspector"><section><h3><Icon name="SlidersHorizontal" :size="16"/>执行配置</h3><p class="small muted">未单独配置时继承作品、角色或全局模型。</p><ModelDefaultSelect scope="NODE" :project-id="project.id" :node-id="selected.id" label="本节点默认模型"/><div v-for="cap in selected.recommendedCapabilities" :key="cap" class="model-binding"><label>{{store.catalog.capabilities.find(c=>c.id===cap)?.name}}</label><select :value="project.nodeBindings[selected.id]?.[cap]??''" @change="setBinding(cap,($event.target as HTMLSelectElement).value)"><option value="">继承上级配置</option><option v-for="m in store.state.models.filter(m=>m.capabilities.includes(cap))" :key="m.id" :value="m.id">{{m.name}} · 未验证</option></select><small>{{resolveModel(store.state,project,selected,cap).source}} · {{resolveModel(store.state,project,selected,cap).model?.name??'未配置'}}</small><details><summary>项目级默认</summary><select :value="project.bindings[cap]??''" @change="setBinding(cap,($event.target as HTMLSelectElement).value,'PROJECT')"><option value="">继承 Agent / 全局</option><option v-for="m in store.state.models.filter(m=>m.capabilities.includes(cap))" :key="m.id" :value="m.id">{{m.name}}</option></select></details></div><p v-if="!selected.recommendedCapabilities.length" class="inspector-note">该步骤优先使用确定性工具或手工操作，无需强行选择大模型。</p><RouterLink to="/models" class="text-link">管理模型<Icon name="ArrowUpRight" :size="14"/></RouterLink></section><section><h3><Icon name="ShieldCheck" :size="16"/>完成标准</h3><p>{{selected.acceptanceCriteria}}</p></section><section><h3><Icon name="UserRoundCheck" :size="16"/>你的决定</h3><p>{{selected.humanAction}}</p></section><section><h3><Icon name="RotateCcw" :size="16"/>需要返工时</h3><p>{{selected.reworkAction}}</p></section><div class="inspector-info"><Icon name="Info" :size="16"/><p>当前版本支持手工交付和流程管理。模型调用与外部执行器尚未启用，不会自动扣费或发布。</p></div></aside></div></div><div v-else class="page-content empty-state"><Icon name="FolderSearch" :size="40"/><h1>找不到这条作品</h1><p>作品可能位于另一个工作区。</p><RouterLink to="/projects" class="btn primary">返回我的作品</RouterLink></div></template>
